    bool operator<(const State& other) const {
        return cost > other.cost;
    }
};

string getGoal(int n, int m) {
    string goal = "";
    for (int i = 0; i < n * m; ++i) {
        if (i == 0) goal += '0';
        else goal += ('0' + i);
    }
    return goal;
