    push_down(node, l, r);
    int mid = (l + r) / 2;
    update(node * 2, l, mid, ql, qr, val);
    update(node * 2 +1, mid + 1, r, ql, qr, val);
    segtree[node].sum = (segtree[node * 2].sum + segtree[node *2 + 1].sum) % MOD;
}

ll query(int node, int l, int r, int ql, int qr) {
