    if (ql <= l && r <= qr) return segtree[node].sum;
    push_down(node, l, r);
    int mid = (l + r) / 2;
    return (query(node * 2, l, mid, ql, qr) + query(node * 2 +1, mid + 1, r, ql, qr)) % MOD;
}

